'use strict';
(()=>{const details=document.getElementById('packet-game'),canvas=document.getElementById('game-canvas'),ctx=canvas.getContext('2d'),stage=document.getElementById('game-stage'),overlay=document.getElementById('game-overlay');let running=false,paused=false,dead=false,y=0,vy=0,distance=0,obstacles=[],spawn=0,last=0,frame=0,market=document.querySelector('[data-region="usa"]')?.getAttribute('aria-pressed')==='true'?'usa':'uk';
const ground=205,playerX=80,size=28;
function destination(){document.getElementById('game-destination').textContent=market==='usa'?'the USA':'the UK';}
function draw(){ctx.clearRect(0,0,1000,260);ctx.fillStyle='#edf5fc';ctx.fillRect(0,0,1000,260);ctx.strokeStyle='#bac9d5';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(0,ground+1);ctx.lineTo(1000,ground+1);ctx.stroke();ctx.fillStyle='#526274';ctx.font='12px monospace';ctx.fillText('SOUTH AFRICA',24,35);ctx.fillText('DESTINATION: '+(market==='usa'?'USA':'UK'),790,35);
ctx.fillStyle='#c5d6e3';for(let i=0;i<16;i++){const x=(i*75-distance*0.18)%1100;if(x<0)continue;const h=20+(i*17)%65;ctx.fillRect(x,ground-h,35,h);}ctx.fillStyle='#fff';for(let i=0;i<6;i++){const x=(i*170-distance*0.35)%1100;ctx.fillRect(x,55+(i%2)*18,60,3);}
ctx.fillStyle='#254b6c';ctx.fillRect(playerX,ground-size-y,size,size);ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.strokeRect(playerX+6,ground-size-y+7,16,13);ctx.beginPath();ctx.moveTo(playerX+6,ground-size-y+7);ctx.lineTo(playerX+14,ground-size-y+14);ctx.lineTo(playerX+22,ground-size-y+7);ctx.stroke();ctx.fillStyle='#c62828';for(const o of obstacles){ctx.fillRect(o.x,ground-o.h,o.w,o.h);ctx.fillStyle='#fff';ctx.font='11px monospace';ctx.fillText('!',o.x+o.w/2-3,ground-o.h+17);ctx.fillStyle='#c62828';}ctx.fillStyle='#526274';ctx.font='11px monospace';ctx.fillText('↑ JUMP OVER CONNECTION TROUBLE',24,238);document.getElementById('game-score').textContent=Math.floor(distance/80);}
function setStatus(text){document.getElementById('game-status').textContent=text;}
function showOverlay(title,copy){overlay.hidden=false;document.getElementById('game-overlay-title').textContent=title;document.getElementById('game-overlay-copy').textContent=copy;}
function end(){running=false;dead=true;cancelAnimationFrame(frame);document.getElementById('game-start').textContent='Try again';document.getElementById('game-pause').disabled=true;showOverlay('Connection interrupted.','Delivered '+Math.floor(distance/80)+' packets. Try again?');setStatus('Run ended. Use Try again to reconnect.');}
function tick(now){if(!running||paused||!details.open)return;let remaining=Math.min(Math.max((now-last)/1000,0),0.25);last=now;while(remaining>0){const dt=Math.min(remaining,1/60);remaining-=dt;const speed=300+Math.min(distance/90,180);distance+=speed*dt;y+=vy*dt;vy-=1800*dt;if(y<0){y=0;vy=0;}spawn-=dt;if(spawn<=0){obstacles.push({x:1020,w:24+Math.random()*16,h:28+Math.random()*24});spawn=1.15+Math.random()*0.8;}for(const o of obstacles){o.x-=speed*dt;if(playerX+size-5>o.x&&playerX+5<o.x+o.w&&y<o.h-5){draw();end();return;}}obstacles=obstacles.filter(o=>o.x>-60);}draw();frame=requestAnimationFrame(tick);}
function start(){cancelAnimationFrame(frame);running=true;paused=false;dead=false;y=0;vy=0;distance=0;obstacles=[];spawn=1;last=performance.now();overlay.hidden=true;document.getElementById('game-start').textContent='Restart run';document.getElementById('game-pause').disabled=false;document.getElementById('game-pause').textContent='Pause';setStatus('Run started. Space, Arrow Up or Jump to avoid obstacles.');stage.focus({preventScroll:true});frame=requestAnimationFrame(tick);}
function jump(){if(running&&!paused&&y===0)vy=620;}
function pause(){if(!running)return;paused=!paused;document.getElementById('game-pause').textContent=paused?'Resume':'Pause';if(paused){cancelAnimationFrame(frame);showOverlay('Route paused.','Resume when you are ready.');setStatus('Paused.');}else{overlay.hidden=true;last=performance.now();frame=requestAnimationFrame(tick);stage.focus({preventScroll:true});setStatus('Run resumed.');}}
function stopWhenHidden(){if(running&&!paused)pause();}
let opened=false;details.addEventListener('toggle',()=>{if(!details.open)stopWhenHidden();else if(!opened){opened=true;draw();}});document.addEventListener('visibilitychange',()=>{if(document.hidden)stopWhenHidden();});document.getElementById('game-start').addEventListener('click',start);document.getElementById('game-jump').addEventListener('click',jump);document.getElementById('game-pause').addEventListener('click',pause);canvas.addEventListener('pointerdown',ev=>{ev.preventDefault();stage.focus({preventScroll:true});jump();});stage.addEventListener('keydown',ev=>{if(['Space','ArrowUp'].includes(ev.code)){ev.preventDefault();jump();}if(ev.code==='KeyP'){ev.preventDefault();pause();}});window.addEventListener('newclearus-market',ev=>{market=ev.detail;destination();if(opened)draw();});destination();
})();
